export enum ASRAnnotation {
    /** Label used when the ASR transcription shouldn't be acted upon (e.g. non-user speech) */
    GARBAGE = 'GARBAGE',
    /** Label used when the ASR transcription was stopped early by Fast EOS */
    FAST_EOS = 'FAST_EOS',
    /** Label used when ASR never detected SOS */
    SOS_TIMEOUT = 'SOS_TIMEOUT',
    /** Label used when ASR continuously receives speech until the max allowed time */
    MAX_SPEECH_TIMEOUT = 'MAX_SPEECH_TIMEOUT'
}

export interface ASRConfig {
    /**
     * Type of encoding for the config
     * @default 'LINEAR16'
     */
    encoding?: 'LINEAR16' | 'FLAC';
    /**
     * The sample rate of the audio.
     * @default 16000
     */
    sampleRate?: number;
    /** Time in ms to wait for start of speech */
    sosTimeout?: number;
    /** Maximum time in ms to wait for final response */
    maxSpeechTimeout?: number;
    /** List of hint phrases to add to Google */
    hints?: string[];
    /** A list of words and phrases for fast EOS */
    earlyEOS?: string[];
}

export interface ASRResult {
    /** String of what Jibo heard */
    text: string;
    /** Jibo's confidence (0-1) that his `text` is correct */
    confidence: number;
    /** Externally applied annotation about the ASRResult (e.g. 'GARBAGE' if thought not to be user speech) */
    annotation?: ASRAnnotation;
}

export interface GlobalMatchResponseData {
    /** Unique ID of the skill */
    skillID: SkillID; 
    /** `true` if skill is on robot */
    onRobot?: boolean;
    /** `true` if this is skill launch */
    launch?: boolean;
    /** `true` if it is proactive launch */
    isProactive?: boolean;
    /** `true` if after this skill exits surprises should be skipped */
    skipSurprises?: boolean;
}

export interface ASRResultOuter {
    isFinal: boolean;
    alternatives: ASRResult[];
    stability: number;
}

export interface ASRResult {
    confidence: number;
    transcript: string;
    words: string[];
}

export interface ASROutput {
    speechEventType: SpeechEventType;
    results?: ASRResultOuter[];
    error?: {
        code: number;
        message: string,
        details: string[];
    };
}

export interface APIAIOutput {
    id: string;
    timestamp: string;
    lang: string;
    result: {
        source: string;
        resolvedQuery: string;
        action: string;
        actionIncomplete: boolean;
        parameters: {
            [key: string]: string | string[]
        };
        contexts: any[];
        metadata: {
            intentName: string,
            intentId: string
        };
        fulfillment: any;
        score: number;
    };
    status: {
        code: number;
    };
    sessionId: string;
}

export enum EventType {
    SKILL_LAUNCH = 'SKILL_LAUNCH'
}

export interface BaseEventData {
    /** Milliseconds since the Epoch */
    timestamp?: number;
    /** UUID of the current session */
    sessionID: string;
    robotID: string;
    skillID: string;
}

export interface SkillLaunchData extends BaseEventData {
    intent?: string;
    personIDs?: string[];
}

export interface SkillPayloadData extends BaseEventData {
    payload: PayloadObject;
}

export interface SkillLaunchRecord extends SkillLaunchData {
    id: string;
    payload?: PayloadObject;
}

export interface PayloadObject {
    [key: string]: PayloadValue;
}

export enum RuleField {
    SKILL_ID = 'skillID',
    INTENT = 'intent',
    PERSON_IDS = 'personIDs',
    PAYLOAD = 'payload',
}

export enum MatchMethod {
    /** For string fields */
    EXACT = 'EXACT',
    /** For string fields */
    NOT = 'NOT',
    /** For string fields */
    ONE_OF = 'ONE_OF',
    /** 
     * For array fields. </br> 
     * Contains string 
     */
    CONTAINS = 'CONTAINS', 
    /** 
     * For array fields. </br> 
     * Does not contain any of strings
     */
    NOT_CONTAIN = 'NOT_CONTAIN',
    CONTAINS_ANY = 'CONTAINS_ANY',
    CONTAINS_ALL = 'CONTAINS_ALL',
}

export interface SimpleRule {
    field: RuleField;
    /** Allowed values */
    value: string | string[];
    match?: MatchMethod;
}

export interface PayloadRule {
    field: RuleField.PAYLOAD;
    value: PayloadObject;
    match?: MatchMethod;
}

export interface PayloadKeyRule {
    field: RuleField.PAYLOAD;
    key: string;
    value: PayloadValue;
    match?: MatchMethod;
}

export interface IHQuery {
    robotID: string;
    /** For exact match by skillID */
    skillID?: string;
    /** For exact match by intent */
    intent?: string;
    /** For exact match by personID */
    personID?: string;
    /** Used to ignore events from current session */
    notSessionID?: string;
    /** 
     * Milliseconds since the Epoch; 
     * the start time of the period of interest. </br>
     * Defaults to full range of available data.
     */
    startTime?: number;
    /** 
     * Milliseconds since the Epoch; 
     * the emd time of the period of interest. </br>
     * Defaults to present.
     */
    endTime?: number;
    /** For advanced matches by skillID, intent, personID, payload */
    rules?: IHQueryRule[];
}

export interface CountResponse {
    count: number;
}

export interface SpeechHistoryBaseData {
    robotID: string;
    accountID: string;
    transID: string;
    timestamp: number;
}

export interface SpeechHistoryUpdate {
    audioFileURL?: string;
    personIDs?: string[];
    asr?: ASRResult;
    nlu?: NLUResult;
    match?: GlobalMatchResponseData;
    redirect?: skill.response.SkillRedirectData;
    skill?: skill.request.SkillRequestOutput;
    error?: hub.response.HubErrorData;
}

export interface SpeechHistoryRecord extends SpeechHistoryBaseData, SpeechHistoryUpdate {
    id: string;
}

export enum HubErrorCode {
    /** Skill URL not found */
    SKILL_NOT_FOUND = 'SKILL_NOT_FOUND',
    /** Timeout while waiting for skill response */
    TIMEOUT_SKILL = 'TIMEOUT_SKILL',
    /** Timeout while waiting for parser response */
    TIMEOUT_PARSER = 'TIMEOUT_PARSER',
    /** Timeout while waiting for ASR response */
    TIMEOUT_ASR = 'TIMEOUT_ASR',
    /** Timeout while waiting for the context message from jetstream */
    TIMEOUT_CONTEXT = 'TIMEOUT_CONTEXT',
    /** Timeout of complete transaction */
    TIMEOUT_TRANSACTION = 'TIMEOUT_TRANSACTION',
    /** Error from ASR service */
    ASR = 'ASR',
    /** Error from Parser service */
    PARSER = 'PARSER',
    /** General error */
    GENERAL = 'GENERAL',
}

export enum ListenMessageMode {
    CLIENT_ASR = 'CLIENT_ASR',
    CLIENT_NLU = 'CLIENT_NLU',
}

export type ListenMessageData = LanguageData & {
    /** Whether this listen was started by hotphrase "Hey Jibo" */
    hotphrase: boolean;
    /** The NLU rules to use for the default agent */
    rules: string[];
    /** Special modes where the client provides either ASR or NLU in separate message */
    mode?: ListenMessageMode;
    /** The configuration of ASR. If `FAKE` then a `FakeASRMessage` will be expected */
    asr?: ASRConfig;
    /** DialogFlow agents to use in addition to the default */
    agents?: { [name: string]: ExternalAgentRequest };
};

export interface ClientASRData {
    text: string;
}

export interface CommandDataInput {
    command: string;
    result: any;
}

export type CommandData = LanguageData & BaseData & {
    input: CommandDataInput;
};

export interface ListenResponseData {
    asr: asr.ASRResult;
    nlu: nlu.NLUResult;
    match?: common.GlobalMatchResponseData;
}

export interface SkillRedirectData {
    match: common.GlobalMatchResponseData;
    memo?: any;
    asr?: asr.ASRResult;
    nlu?: nlu.NLUResult;
}

export enum ListenResultState {
    /**
     * No input was received - user did not say anything before we stopped listening.
     */
    noInput = 'noInput',
    /**
     * User said something, but it didn't match anything that we were listening for.
     */
    noMatch = 'noMatch',
    /**
     * User said something that matched what we were listening for. `nlu` can be expected to
     * exist and have valid data.
     */
    match = 'match'
}

export interface HubErrorData {
    message: string;
    code?: HubErrorCode;
}

export type HubResponse = SoSResponse | EoSResponse |
    ASRResponse | NLUResponse | ListenResponse | SkillRedirectResponse |
    proactive.ProactiveResponse | ErrorResponse | skill.response.SkillResponse;

export interface LogLevels {
    [namespace: string]: LogLevel;
}

export interface OutputPerNamespace {
    [namespace: string]: LevelPerOutput;
}

export interface LevelPerOutput {
    [output: string]: LogLevel;
}

export interface GeneralData {
    /** Account ID of the robot */
    accountID: string;
    /** My-Friendly-Robot-Name */
    robotID: string;
    /** Language code for the robot */
    lang: LanguageCode;
    /** Full-stack release version of the robot */
    release: string;
    /** Robot IP address */
    remoteAddress?: string;
}

export interface SkillData {
    /** Unique skill ID */
    id: string;
    /** Info for each session */
    session?: {
        /** UUID for current session of skill */
        id: string;
        /** Active node in skill */
        nodeID: number;
        /** A read/write session for skill data */
        data: any;
        /** History of transitions */
        trace: {
            nodeID: number;
            transition: string
        }[];
    };
}

export interface Dialog {
    /** Dialog history */
    history: DialogTurn[];
}

export interface DialogTurn extends nlu.NLUResult {
    skillID?: string;
    mimID?: string;
    personID?: string;
}

export interface Person {
    /** UUID of LPS system mapping to entity, including looper ID if recognized. */
    id: string;
    /** Type of entity recognized. */
    type: SensoryType | IDLabels;
    /** Confidence in the recognition. */
    confidence: number;
}

export interface LooperInfo {
    /** Loop member's first name. */
    firstName: string;
    /** Loop member's last name. */
    lastName: string;
    /** Loop member's phonetic name. */
    phoneticName: string;
    /** Loop member's gender. */
    gender: string;
    /** Unix epoch timestamp of loop member's birthday. */
    birthdate: number;
    /** Loop member's loop ID. */
    id: string;
    /** Loop member's account ID */
    accountId: string;
}

export interface JiboInfo {
    /** Jibo's exterior color */
    color: JiboColor;
    /** Jibo's birthdate (unix epoch timestamp from the moment he was first turned on) */
    /** ID of the loop Jibo is in */
    birthdate: number;
    id: string;
}

export interface LoopContext {
    /** Information about every Loop member (except Jibo). */
    users: LooperInfo[];
    /** Information about Jibo himself. */
    jibo: JiboInfo;
    /** Loop id of the owner of the Loop. */
    owner: string;
    loopId: string;
}

export interface EmotionContext {
    /** Current nearest emotion. */
    name: string;
    /** Current valence. */
    valence: number;
    /** Current confidence. */
    confidence: number;
}

export interface MotivationContext {
    /** Current social drive state. */
    social: number;
    /** Current playful drive state. */
    playful: number;
}

export interface CharacterContext {
    /** Current emotion context. */
    emotion: EmotionContext;
    /** Current motivation context. */
    motivation: MotivationContext;
}

export interface LocationContext {
    /** Jibo's current city (or nearest) */
    city: string;
    /** Jibo's current state */
    state: string;
    /** ISO 3166 1 alpha 2 spec compliant state (or political equivalent) abbreviation of Jibo's current location */
    stateAbbr: string;
    /** Jibo's current country */
    country: string;
    /** ISO 3166 1 alpha 2 spec compliant country code of Jibo's current country. */
    countryCode: string;
    /** Jibo's current latitude */
    lat: number;
    /** Jibo's current longitude */
    lng: number;
    /** ISO 8601 compliant string representing Jibo's current time/timezone. */
    iso: string;
}

export interface PerceptionContext {
    /** ID of the currently active speaker. */
    speaker: string;
    /** Data about currently detected present people. */
    peoplePresent: Person[];
}

export interface DialogContext {
    /** ID of a loop member that was referred to in utterance. */
    referent?: string;
}

export interface RuntimeContext {
    /** Information about Jibo's character state. */
    character: CharacterContext;
    /** Information about Jibo's current location. */
    location: LocationContext;
    /** Information about Jibo's loop. */
    loop: LoopContext;
    /** Information about Jibo's perception state. */
    perception: PerceptionContext;
    /** Information derived from the last turn of Dialog with Jibo. */
    dialog: DialogContext;
}

export interface LanguageData {
