export interface ContextRule {
    field: string;
    /**
     * `Contain` match rules only apply to collection data types (arrays and objects).
     * Comparison rules (`GREATER_THAN`, `LESS_THAN`, etc) only apply to comparable
     * data types (numbers, mostly)
     */
    matchRule: ContextMatchRule;
    value: any;
}

export enum IHQueryType {
    LastEvent = 'LastEvent',
    Count = 'Count'
}

export enum IHTimeOffset {
    SinceWaking = 'SinceWaking',
}

export enum IHTransformMethod {
    TimeSince = 'TimeSince',
}

export enum IHMatchMethod {
    EXACT = 'EXACT',
    NOT = 'NOT',
    GREATER_THAN = 'GREATER_THAN',
    LESS_THAN = 'LESS_THAN',
}

export interface IHRule {
    /* query to make to history service */
    query: IHQueryID | IHQueryDefinition;
    /* optional value transformation, ex: TimeSince */
    transform?: IHTransformMethod;
    /* optional nested property to check instead of full result, ex: payload.someKey1 */
    checkProperty?: string;
    /* match method to apply */
    matchRule: IHMatchMethod;
    /* expected value */
    value: TimePeriod | number | string | null;
}

export interface IHQueryDefinition {
    type: IHQueryType;
    personID?: IHQueryPerson;
    queryRules: IHQueryRule[];
    startTimeOffset?: TimePeriod | IHTimeOffset;
    endTimeOffset?: TimePeriod | IHTimeOffset;
}

export interface IHQueryDefinitions {
    [key: string]: IHQueryDefinition;
}

