export interface BaseMessage<T extends string, D> {
    /** The type of this message, describes what kind of data to expect */
    type: T;
    /** An id that is unique per message */
    msgID: UUID;
    /** A timestamp in number of milliseconds elapsed since 1 January 1970 00:00:00 UTC */
    ts: number;
    /** The data for this message */
    data: D;

    // TODO decide if we want to add these version messages
    // // The version of the sender, or versions of components of sender
    // version: {
    //     // The version of the sender of this message
    //     this: Version;
    //     // Versions of other relevant components of the message
    //     [component: string]: Version;
    // };
}

export type BaseResponse<T extends string, D> = BaseMessage<T, D> & {
    final?: boolean;    // Is this the final response in a transaction
    timings?: Timings;
};

export interface Timings {
